# ===== UNIT 2: HEALTH CARE DELIVERY SYSTEM IN NEPAL (15 new) =====
q.append({"unit_id": "phs-unit-2", "question_text": "The Declaration of Alma-Ata, which launched the Primary Health Care approach, was made in the year:", "options": ["1978", "1948", "1988", "2000"], "correct_index": 0, "explanation": "In September 1978 the international conference at Alma-Ata, USSR, adopted the declaration calling for Health for All through Primary Health Care.", "difficulty": "easy", "tags": ["healthcare delivery", "Alma Ata"]})
