q.append({"unit_id": "phs-unit-2", "question_text": "Community participation in Primary Health Care means that people:", "options": ["Take part in planning and running their own health services", "Only pay fees at the hospital counter", "Wait passively for government help", "Are excluded from all health decisions"], "correct_index": 0, "explanation": "PHC rests on communities identifying their own needs and contributing to planning, implementation and evaluation of health activities.", "difficulty": "medium", "tags": ["healthcare delivery", "PHC principles"]})
